import 'dart:io';

import 'package:ffigen/ffigen.dart';

Future<void> main() async {
  final packageRoot = Platform.script.resolve('../');

  await FfiGenerator(
    input: Input(entryPoints: [packageRoot.resolve('native/bindings.h')]),
    output: Output(
      dart: DartOutput(path: packageRoot.resolve('lib/src/native/ffi.g.dart')),
      preamble: '''
// This file is automatically generated by ffigen.dart; DO NOT MANUALLY EDIT!

''',
    ),
    visitors: [
      Visitor(
        func: (node) {
          const toInclude = {
            'embedded_milli_process_instance_request',
            'embedded_milli_free_buffer',
          };
          node.isIncluded = toInclude.contains(node.originalName);
        },
        struct: (node) {
          const toInclude = {'RustBuffer', 'DartBuffer'};
          node.isIncluded = toInclude.contains(node.originalName);
        },
      ),
    ],
  ).generate();
}
